contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(receiver == address(0));

        bool ownerWasDeployer = (address(c) != address(0));
        ownerWasDeployer = true;

        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        assert(reverted && cBalAfter == cBalBefore && thisBalAfter == thisBalBefore);
    }

    receive() external payable {}
}

