pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(address receiver, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        receiver = address(0);
        bool ownerWasDeployer = (address(c) != address(0));
        ownerWasDeployer = true;
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;
        assertTrue(reverted && cBalAfter == cBalBefore && thisBalAfter == thisBalBefore);
    }

    function testFuzz_run(address receiver, uint256 amount) public {
        _run(receiver, amount);
    }

    receive() external payable {}
}
